const NICKNAME_TO_FORMAL = {
  bob: 'robert', bill: 'william', liz: 'elizabeth', kathy: 'katherine',
  mike: 'michael', jen: 'jennifer', jon: 'jonathan', chris: 'christopher',
  nick: 'nicholas', debbie: 'deborah', maggie: 'margaret', pat: 'patricia',
  tim: 'timothy', ben: 'benjamin', sam: 'samuel', becky: 'rebecca',
  steph: 'stephanie', greg: 'gregory', tony: 'anthony', kim: 'kimberly'
};

function canonicalFirstName(first) {
  const lower = (first || '').trim().toLowerCase();
  return NICKNAME_TO_FORMAL[lower] || lower;
}

const first = $json.first_name || '';
const last = $json.last_name || '';
const canonicalFirst = canonicalFirstName(first);
const normalizedName = `${canonicalFirst} ${last.trim().toLowerCase()}`.trim();
const normalizedEmail = ($json.email || '').trim().toLowerCase();
const normalizedPhone = ($json.phone || '').replace(/\D/g, '');

return {
  ...$json,
  normalized_name: normalizedName,
  normalized_email: normalizedEmail,
  normalized_phone: normalizedPhone
};

function levenshtein(a, b) {
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  const dp = Array.from({length: m + 1}, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost);
    }
  }
  return dp[m][n];
}

function nameSimilarity(a, b) {
  if (!a || !b) return 0;
  const maxLen = Math.max(a.length, b.length);
  if (maxLen === 0) return 1;
  return 1 - levenshtein(a, b) / maxLen;
}

function completeness(c) {
  return ['first_name', 'last_name', 'email', 'phone', 'company_name']
    .filter(f => c[f] && String(c[f]).trim() !== '').length;
}

const contacts = items.map(item => item.json);

// Block by first 3 letters of normalized last name - avoids full N^2 comparison,
// same pattern that matters at 33K-65K scale even though it's not strictly
// necessary at this demo's ~1,000 rows.
const blocks = {};
for (const c of contacts) {
  const lastName = (c.normalized_name || '').split(' ').slice(1).join(' ');
  const key = lastName.slice(0, 3) || '___';
  if (!blocks[key]) blocks[key] = [];
  blocks[key].push(c);
}

const pairs = [];
const seen = new Set();

for (const key in blocks) {
  const group = blocks[key];
  for (let i = 0; i < group.length; i++) {
    for (let j = i + 1; j < group.length; j++) {
      const a = group[i], b = group[j];
      const pairKey = [a.id, b.id].sort().join('-');
      if (seen.has(pairKey)) continue;
      seen.add(pairKey);

      const phoneMatch = a.normalized_phone && b.normalized_phone && a.normalized_phone === b.normalized_phone;
      const emailMatch = a.normalized_email && b.normalized_email && a.normalized_email === b.normalized_email;
      const nameSim = nameSimilarity(a.normalized_name, b.normalized_name);
      const companyMatch = a.company_name && b.company_name &&
        a.company_name.trim().toLowerCase() === b.company_name.trim().toLowerCase();

      let confidence = 0;
      const matchedFields = [];

      if (phoneMatch) {
        confidence = 0.95;
        matchedFields.push('phone exact match');
      } else if (emailMatch) {
        confidence = 0.95;
        matchedFields.push('email exact match');
      } else if (nameSim >= 0.85 && companyMatch) {
        confidence = 0.80;
        matchedFields.push('name similarity', 'company match');
      } else if (nameSim >= 0.85) {
        confidence = 0.50;
        matchedFields.push('name similarity only');
      }

      if (confidence < 0.40) continue;

      const aScore = completeness(a);
      const bScore = completeness(b);
      let survivorId, loserId;
      if (aScore > bScore) { survivorId = a.id; loserId = b.id; }
      else if (bScore > aScore) { survivorId = b.id; loserId = a.id; }
      else { survivorId = Math.min(a.id, b.id); loserId = Math.max(a.id, b.id); }

      pairs.push({
        json: {
          contact_a_id: a.id,
          contact_b_id: b.id,
          survivor_id: survivorId,
          loser_id: loserId,
          confidence_score: confidence,
          matched_fields: matchedFields.join(', ')
        }
      });
    }
  }
}

return pairs;

const REGION_BY_STATE = {
  CT: 'Northeast', ME: 'Northeast', MA: 'Northeast', NH: 'Northeast', RI: 'Northeast', VT: 'Northeast', NJ: 'Northeast', NY: 'Northeast', PA: 'Northeast',
  IL: 'Midwest', IN: 'Midwest', MI: 'Midwest', OH: 'Midwest', WI: 'Midwest', IA: 'Midwest', KS: 'Midwest', MN: 'Midwest', MO: 'Midwest', NE: 'Midwest', ND: 'Midwest', SD: 'Midwest',
  DE: 'South', FL: 'South', GA: 'South', MD: 'South', NC: 'South', SC: 'South', VA: 'South', WV: 'South', AL: 'South', KY: 'South', MS: 'South', TN: 'South', AR: 'South', LA: 'South', OK: 'South', TX: 'South',
  AZ: 'West', CO: 'West', ID: 'West', MT: 'West', NV: 'West', NM: 'West', UT: 'West', WY: 'West', AK: 'West', CA: 'West', HI: 'West', OR: 'West', WA: 'West'
};

const REP_BY_REGION = {
  Northeast: 'Priya Desai',
  Midwest: 'Marcus Webb',
  South: 'Alicia Turner',
  West: 'Daniel Cho'
};

const state = ($json.state || '').trim().toUpperCase();
const region = REGION_BY_STATE[state];
const owner = region ? REP_BY_REGION[region] : 'Unassigned - needs territory review';

return {
  ...$json,
  owner
};

const high = items.filter(i => i.json.confidence_score >= 0.70).length;
const low = items.length - high;

return [{
  json: {
    count: items.length,
    high_confidence_count: high,
    low_confidence_count: low
  }
}];
